INSERT INTO public.lessons (stage_id, source_key, lesson_number, title, title_arabic, description, duration_minutes, cefr_target, approach, unlock_condition, icon, gradient, display_order, dialect_module, status, can_do, grammar_notes, culture_notes, dialogue, sound_spotlight, lesson_sequence, real_world_prompts)
SELECT s.id, $hk$egyptian/s1/l01$hk$, 1, $hk$Objects — The World Around You$hk$, $hk$الحاجات اللي حواليك$hk$, $hk$Twelve things you can point at right now — a glass of water, the door, your phone — heard in Cairo Arabic and seen until the sound and the thing are one. No reading, no speaking yet.$hk$, 15, $hk$Pre-A1$hk$, $hk$GPA Phase 1 — Here & Now. Receptive only: listen, look, tap. No production, no grammar meta-language.$hk$, $hk$≥9/12 correct on the final listen-and-tap quiz$hk$, $hk$🏠$hk$, $hk$bg-gradient-green$hk$, 101, $hk$Egyptian$hk$, 'published', $hk$["Recognise twelve everyday objects by sound and picture","Match a spoken Egyptian word to the thing it names"]$hk$::jsonb, $hk$[]$hk$::jsonb, $hk$[{"title":"The glass of tea is where the language starts","note":"Walk into any Egyptian home, shop or office and before anything else you will be asked what you drink. Tea (شاي) is the default — black, strong, and sweet unless you say otherwise — and Turkish-style coffee (قهوة) comes in a small cup, ordered by its sugar level. Say yes the second time you are asked, not the first: the first offer is the ritual, the second is the invitation. Learning these two words before anything else is not an accident; they are the first words a host will say to you.","phrases":[{"arabic":"تشرب إيه؟ شاي ولا قهوة؟","transliteration":"tishrab eeh? shaay walla ʾahwa?","english":"What will you drink? Tea or coffee?"},{"arabic":"مية لو سمحت","transliteration":"mayya law samaḥt","english":"Water, please"}]}]$hk$::jsonb, $hk$[{"speaker":"Host","arabic":"اتفضل، شاي؟","transliteration":"itfaḍḍal, shaay?","english":"Please — tea?"},{"speaker":"Guest","arabic":"مية لو سمحت","transliteration":"mayya law samaḥt","english":"Water, please"},{"speaker":"Host","arabic":"المية على الكرسي","transliteration":"el-mayya ʿala l-kursi","english":"The water is on the chair"},{"speaker":"Guest","arabic":"شكراً","transliteration":"shukran","english":"Thanks"}]$hk$::jsonb, $hk$[{"sound":"ج → g","example":"شجرة (shagara)","explanation":"In Cairo ج is a hard g as in 'go', never the j of MSA or the Levant. It is the single most recognisable Egyptian sound, and it is introduced through the first word that has it."},{"sound":"ق → ʾ","example":"قهوة (ʾahwa)","explanation":"Written ق, but in everyday Cairo speech it is a catch in the throat, like the gap in 'uh-oh'. Learners must learn to read ق and hear ʾ. A handful of learned words keep the q (القرآن، القاهرة) — those come later."},{"sound":"ع","example":"عيش (ʿeesh)، عربية (ʿarabiyya)","explanation":"A squeezed sound from deep in the throat, unlike anything in English. Heard passively here in two of the most useful words; production practice starts in Lesson 3."},{"sound":"Long ee","example":"بيت (beet)، عيش (ʿeesh)","explanation":"Where other dialects say bayt, Cairo says beet — a long, pure ee. Hearing it in two words side by side lets the pattern register before it is ever explained."}]$hk$::jsonb, $hk$[{"step":"Welcome","detail":"A warm Cairo street scene — balconies, a palm, a tea tray. One line of English: you will start recognising twelve Egyptian words. Tap يلا to begin."},{"step":"Listen & see","detail":"Each of the 12 words on its own full-screen card: illustration, native Cairo audio auto-plays, Arabic large, no English yet. Tap to replay as often as you like."},{"step":"Second pass","detail":"The same 12 cards, faster, audio auto-plays, English label now shown small and grey underneath."},{"step":"Tap quiz — round 1","detail":"Audio only; four images in a grid; tap the one you heard. Words 1–6. Distractors come from this lesson."},{"step":"Tap quiz — round 2","detail":"Same format, words 7–12."},{"step":"Tap quiz — all twelve","detail":"Random order, audio only. Score screen shows the missed words with image and audio to replay."},{"step":"Lesson complete","detail":"Words-learned counter rolls up to 12. Nudge: look around you today and find these things."}]$hk$::jsonb, $hk$[{"prompt":"Look around you right now. Can you spot any of the twelve things from this lesson? Say the Egyptian word in your head.","context":"Shown on the lesson-complete screen. Observation only, no speaking required. Activates all 12 words."},{"prompt":"Every time you make or drink شاي or مية over the next few days, say the word once out loud.","context":"Follow-up notification the next morning (optional). Two of the highest-frequency words, both in every kitchen."},{"prompt":"If you have a tutor session coming up, tell them: 'I just learned these twelve words — can you point at them and say them?'","context":"The ideal first tutor interaction: the GPA here-and-now game. Receptive reinforcement only."}]$hk$::jsonb
FROM public.curriculum_stages s WHERE s.stage_number = 1
