INSERT INTO public.vocabulary_words (lesson_id, dialect_module, word_arabic, word_english, transliteration, category, teaching_note, image_scene_description, example_arabic, example_transliteration, example_english, display_order)
SELECT l.id, $hk$Egyptian$hk$, v.word_arabic, v.word_english, v.transliteration, v.category, v.teaching_note, v.image_scene_description, v.example_arabic, v.example_transliteration, v.example_english, v.display_order
FROM (VALUES
  ($hk$مية$hk$, $hk$water$hk$, $hk$mayya$hk$, $hk$Food & drink$hk$, $hk$Universal and unambiguous. The Egyptian word is مية (mayya), with a doubled y — not the MSA ماء, and not the Gulf ماي. You will hear it a hundred times a day in summer.$hk$, $hk$Close-up of a clear glass of cold water on a table, condensation on the glass, a plastic water bottle beside it.$hk$, $hk$المية باردة$hk$, $hk$el-mayya barda$hk$, $hk$The water is cold$hk$, 1),
  ($hk$قهوة$hk$, $hk$coffee$hk$, $hk$ʾahwa$hk$, $hk$Food & drink$hk$, $hk$Culturally central and the first meeting with the Egyptian ق: it is written ق but said as a catch in the throat, ʾahwa. Learners who say qahwa sound like a newsreader. The same word means the neighbourhood café (الأهوة).$hk$, $hk$A small white Turkish-coffee cup on a saucer with thick dark coffee, a long-handled brass kanaka pot behind it.$hk$, $hk$قهوة مظبوط لو سمحت$hk$, $hk$ʾahwa maẓbuuṭ law samaḥt$hk$, $hk$A medium-sweet coffee, please$hk$, 2),
  ($hk$شاي$hk$, $hk$tea$hk$, $hk$shaay$hk$, $hk$Food & drink$hk$, $hk$The national drink, served in a glass, black and sweet. The same word across the Arab world, so it is a free win — and the first ش sound.$hk$, $hk$A small glass of dark red-brown tea on a metal tray, a sugar bowl beside it, a sprig of mint on top.$hk$, $hk$شاي بالنعناع$hk$, $hk$shaay bin-niʿnaaʿ$hk$, $hk$Tea with mint$hk$, 3),
  ($hk$عيش$hk$, $hk$bread$hk$, $hk$ʿeesh$hk$, $hk$Food & drink$hk$, $hk$Egyptians call bread عيش — literally 'life'. The MSA and Levantine خبز will be understood but marks you as a foreigner at once. Introduces the ع sound at the start of a word.$hk$, $hk$A stack of round puffed Egyptian baladi flatbreads on a wooden board, one torn open to show the pocket.$hk$, $hk$العيش سخن$hk$, $hk$el-ʿeesh sukhn$hk$, $hk$The bread is hot$hk$, 4),
  ($hk$كرسي$hk$, $hk$chair$hk$, $hk$kursi$hk$, $hk$Home$hk$, $hk$Furniture is ideal early vocabulary — stable, pointable, unambiguous. Same word everywhere in Arabic.$hk$, $hk$A simple wooden chair with a cane seat against a plain light wall, nothing else in frame.$hk$, $hk$اقعد على الكرسي$hk$, $hk$uʾʿud ʿala l-kursi$hk$, $hk$Sit on the chair$hk$, 5),
  ($hk$باب$hk$, $hk$door$hk$, $hk$baab$hk$, $hk$Home$hk$, $hk$Short, phonetically simple, and it carries the long aa the learner will meet again in كتاب. Egyptians knock and call يا باب? — not literally, but the word is everywhere.$hk$, $hk$A wooden apartment door slightly ajar with warm light coming through the gap, a brass knocker on it.$hk$, $hk$الباب مفتوح$hk$, $hk$el-baab maftuuḥ$hk$, $hk$The door is open$hk$, 6),
  ($hk$بيت$hk$, $hk$house / home$hk$, $hk$beet$hk$, $hk$Home$hk$, $hk$Very high frequency; it returns in dozens of later phrases (بيتي، بيتك، بيتنا). Note the Egyptian vowel: beet, a long ee, not bayt. That ee sound is the most audible mark of a Cairo accent.$hk$, $hk$Exterior of a Cairo apartment building in warm light, balconies with washing lines and potted plants, a small shop at street level.$hk$, $hk$ده بيتي$hk$, $hk$da beeti$hk$, $hk$This is my house$hk$, 7),
  ($hk$عربية$hk$, $hk$car$hk$, $hk$ʿarabiyya$hk$, $hk$Outdoor$hk$, $hk$The everyday Egyptian word for a car is عربية, not سيارة (which is what the sign on a car-hire office says). Confusingly the same word also means 'Arabic' as an adjective — context always tells you which. Doubled يّ.$hk$, $hk$A white saloon car parked under a tree on a quiet Cairo side street, seen from the side.$hk$, $hk$العربية بره$hk$, $hk$el-ʿarabiyya barra$hk$, $hk$The car is outside$hk$, 8),
  ($hk$شجرة$hk$, $hk$tree$hk$, $hk$shagara$hk$, $hk$Outdoor$hk$, $hk$The first ج of the course, and in Cairo ج is a hard g: shagara, never shajara. Say it the Cairo way from day one — it is the sound Egyptians notice first in a foreigner. Cairo's streets are lined with ficus and palms, so trees are pointable.$hk$, $hk$A tall date palm beside a leafy ficus tree on a Cairo street corner, clear blue sky.$hk$, $hk$الشجرة كبيرة$hk$, $hk$esh-shagara kibiira$hk$, $hk$The tree is big$hk$, 9),
  ($hk$موبايل$hk$, $hk$phone / mobile$hk$, $hk$mobaayl$hk$, $hk$Object$hk$, $hk$A borrowed word, so nearly free. Egyptians say موبايل for the phone in their hand and تليفون for a call or a landline; both are accepted. Gulf جوال will not be understood in Cairo.$hk$, $hk$A smartphone lying face-up on a café table, screen lit, next to a glass of tea.$hk$, $hk$الموبايل فين؟$hk$, $hk$el-mobaayl feen?$hk$, $hk$Where is the phone?$hk$, 10),
  ($hk$كتاب$hk$, $hk$book$hk$, $hk$kitaab$hk$, $hk$Object$hk$, $hk$Classic object-lesson word; long aa vowel, and the ك–ت–ب root the learner will meet again in 'write' and 'office'. Same word in every dialect.$hk$, $hk$A closed hardback book on a desk, plain cover, a pen resting on top.$hk$, $hk$الكتاب على الكرسي$hk$, $hk$el-kitaab ʿala l-kursi$hk$, $hk$The book is on the chair$hk$, 11),
  ($hk$مفتاح$hk$, $hk$key$hk$, $hk$muftaaḥ$hk$, $hk$Object$hk$, $hk$Everyday and pocket-sized. Introduces the ح sound at the end of a word, where it is easiest to hear. Egyptians say muftaaḥ with u in the first syllable.$hk$, $hk$A single metal key on a keyring against a plain background.$hk$, $hk$المفتاح في العربية$hk$, $hk$el-muftaaḥ fil-ʿarabiyya$hk$, $hk$The key is in the car$hk$, 12)
) AS v(word_arabic, word_english, transliteration, category, teaching_note, image_scene_description, example_arabic, example_transliteration, example_english, display_order)
CROSS JOIN public.lessons l
WHERE l.source_key = $hk$egyptian/s1/l01$hk$
