SELECT 'grammar', $hk$pronouns$hk$, $hk$Egyptian$hk$, $hk$Pronouns$hk$, $hk$Pre-A1$hk$, s.id, 'curriculum-tracks', '{}'::jsonb
FROM public.curriculum_stages s WHERE s.stage_number = 1
ON CONFLICT (kind, key, dialect) DO NOTHING;
