SELECT c.id, $hk$Egyptian$hk$, $hk$بشرب$hk$, ARRAY[$hk$بيشرب$hk$, $hk$بتشرب$hk$, $hk$بنشرب$hk$, $hk$بتشربي$hk$, $hk$بيشربوا$hk$, $hk$اشرب$hk$]::text[], $hk$bashrab$hk$, 'draft', 'curriculum-tracks'
