SELECT 'grammar', $hk$sentence-structure$hk$, $hk$Egyptian$hk$, $hk$Sentence structure$hk$, $hk$B1$hk$, s.id, 'curriculum-tracks', '{}'::jsonb
FROM public.curriculum_stages s WHERE s.stage_number = 3
ON CONFLICT (kind, key, dialect) DO NOTHING;
