-- yemeni/s1/l06 · Numbers One to Ten
INSERT INTO public.lessons (stage_id, source_key, lesson_number, title, title_arabic, description, duration_minutes, cefr_target, approach, unlock_condition, icon, gradient, display_order, dialect_module, status, can_do, grammar_notes, culture_notes, dialogue, sound_spotlight, lesson_sequence, real_world_prompts)
SELECT s.id, $hk$yemeni/s1/l06$hk$, 6, $hk$Numbers One to Ten$hk$, $hk$الأرقام من واحد إلى عشرة$hk$, $hk$Count from one to ten the way Sanaa does — with the th kept in ثنين and ثلاثة — ask how much something costs, understand a price in riyals, and read out a phone number digit by digit.$hk$, 20, $hk$A1$hk$, $hk$GPA Phase 2 — objects counted on screen, fingers and coins as the here-and-now. Numbers are drilled as a chant first, then pulled apart for prices and phone numbers.$hk$, $hk$≥9/12 on the listen-and-tap quiz and a phone number read aloud correctly$hk$, $hk$🔢$hk$, $hk$bg-gradient-charcoal$hk$, 106, $hk$Yemeni$hk$, 'published', $hk$["Count from one to ten","Ask how much something costs and understand the answer","Say a phone number digit by digit"]$hk$::jsonb, $hk$[{"category":"questions","title":"بكم؟ and كم؟ — how much, how many","explanation":"For a price, Yemen asks بكم — 'for how much': بكم الخبز؟ 'how much is the bread?'. The answer is a number plus ريال: بخمسة ريال 'for five riyals'. For counting things, كم on its own: كم جاهل عندك؟ 'how many kids do you have?' — and the thing counted stays singular after كم. The question word can start the sentence or end it; both are natural in Sanaa.","examples":[{"arabic":"بكم الخبز؟","transliteration":"bikam il-khubz?","english":"How much is the bread?"},{"arabic":"الخبز بخمسة ريال","transliteration":"il-khubz bi-khamsa riyaal","english":"The bread is five riyals"},{"arabic":"كم شاهي تشتي؟","transliteration":"kam shaahi tishti?","english":"How many teas do you want?"},{"arabic":"ثنين شاهي لو سمحت","transliteration":"thnayn shaahi law samaḥt","english":"Two teas, please"}]}]$hk$::jsonb, $hk$[{"title":"Riyals, change and the first price","note":"Yemen's money is the ريال, and after any number the word stays singular: خمسة ريال, عشرة ريال. Coins have all but vanished, so small change means small notes, and a shopkeeper who has none will round in your favour or hand you a sweet. The first price you hear in a souq is an opening, not a verdict: ask بكم, look doubtful, and offer less with a smile — but in a bakery, a bus or a pharmacy the price is the price. Yemenis also count on their fingers starting from the little finger, and hold up the whole hand for five.","phrases":[{"arabic":"بكم ذا؟","transliteration":"bikam dhaa?","english":"How much is this?"},{"arabic":"غالي! بعشرة ريال؟","transliteration":"ghaali! bi-ʿashara riyaal?","english":"Expensive! For ten riyals?"},{"arabic":"هات الزلط","transliteration":"haat iz-zalaṭ","english":"Hand over the money"}]}]$hk$::jsonb, $hk$[{"speaker":"Customer","arabic":"السلام عليكم. بكم الخبز؟","transliteration":"is-salaam ʿalaykum. bikam il-khubz?","english":"Peace be upon you. How much is the bread?"},{"speaker":"Baker","arabic":"وعليكم السلام. الواحد بخمسة ريال","transliteration":"wa-ʿalaykum is-salaam. il-waaḥid bi-khamsa riyaal","english":"And upon you peace. One is five riyals"},{"speaker":"Customer","arabic":"طيب، هات ثلاثة","transliteration":"ṭayyib, haat thalaatha","english":"Okay, give me three"},{"speaker":"Baker","arabic":"ثلاثة… عشرة ريال وخمسة. تفضّل","transliteration":"thalaatha… ʿashara riyaal w-khamsa. tfaḍḍal","english":"Three… ten riyals and five. Here you are"},{"speaker":"Customer","arabic":"تفضّل الزلط. شكراً","transliteration":"tfaḍḍal iz-zalaṭ. shukran","english":"Here's the money. Thanks"},{"speaker":"Baker","arabic":"العفو، حياك الله","transliteration":"il-ʿafw, ḥayyaak allaah","english":"You're welcome — come again"}]$hk$::jsonb, $hk$[{"sound":"ث","example":"ثنين، ثلاثة، ثمانية","explanation":"The th of English 'think'. Sanaa keeps it where Aden, Cairo and much of the Gulf turn it into t or s — three of the ten numbers carry it, so counting is the drill."},{"sound":"ع inside a number","example":"أربعة، سبعة، تسعة، عشرة","explanation":"Four numbers have ع before the final a. Say each slowly and let the throat close: ar-ba-ʿa, sab-ʿa, tis-ʿa, ʿa-sha-ra."},{"sound":"The dropped -a","example":"خمسة → الساعة خمس","explanation":"Before a noun and when telling time, the final -a of a number disappears in Sanaa: خمس ريال, الساعة عشر. Hear it now; use it in the time lesson."}]$hk$::jsonb, $hk$[{"step":"Welcome","detail":"A bakery counter with breads stacked in threes. One line of English: you will count to ten and buy something."},{"step":"Count along","detail":"Ten cards, one number each, with the objects counted on screen; audio plays as a chant, then one by one."},{"step":"Listen & see","detail":"The three money cards (بكم، زلط، ريال) with illustration and audio; second pass with English."},{"step":"How many?","detail":"Objects appear in a group; audio says a number; tap the matching group. Then reversed: see a group, tap the number you hear."},{"step":"Price tags","detail":"A vendor says a price; tap the right banknote combination. Trains بـ + number + ريال."},{"step":"Read a number","detail":"A phone number appears digit by digit; record yourself reading it; compare to the model. Feedback on ث and ع."},{"step":"Lesson complete","detail":"Counter rolls up. Nudge: count something around you to ten in Arabic tonight."}]$hk$::jsonb, $hk$[{"prompt":"Count the stairs, the plates or the cars outside to ten in Sanaa Arabic — ث in ثنين and ثلاثة, ع in أربعة.","context":"Shown on the lesson-complete screen. Here-and-now counting with real objects."},{"prompt":"Next time you pay for anything, ask بكم؟ first even if you can see the price, and listen for the number.","context":"Follow-up notification. Uses the price question in a real exchange."},{"prompt":"Read your own phone number to your tutor digit by digit, then ask them to read theirs back to you.","context":"Tutor prompt. Two-way number recognition."}]$hk$::jsonb
FROM public.curriculum_stages s WHERE s.stage_number = 1
ON CONFLICT (source_key) DO UPDATE SET lesson_number = EXCLUDED.lesson_number, title = EXCLUDED.title, title_arabic = EXCLUDED.title_arabic, description = EXCLUDED.description, duration_minutes = EXCLUDED.duration_minutes, cefr_target = EXCLUDED.cefr_target, approach = EXCLUDED.approach, unlock_condition = EXCLUDED.unlock_condition, icon = EXCLUDED.icon, gradient = EXCLUDED.gradient, display_order = EXCLUDED.display_order, dialect_module = EXCLUDED.dialect_module, status = EXCLUDED.status, can_do = EXCLUDED.can_do, grammar_notes = EXCLUDED.grammar_notes, culture_notes = EXCLUDED.culture_notes, dialogue = EXCLUDED.dialogue, sound_spotlight = EXCLUDED.sound_spotlight, lesson_sequence = EXCLUDED.lesson_sequence, real_world_prompts = EXCLUDED.real_world_prompts, stage_id = EXCLUDED.stage_id;
INSERT INTO public.vocabulary_words (lesson_id, dialect_module, word_arabic, word_english, transliteration, category, teaching_note, image_scene_description, example_arabic, example_transliteration, example_english, display_order)
SELECT l.id, $hk$Yemeni$hk$, v.word_arabic, v.word_english, v.transliteration, v.category, v.teaching_note, v.image_scene_description, v.example_arabic, v.example_transliteration, v.example_english, v.display_order
FROM (VALUES
  ($hk$واحد$hk$, $hk$one$hk$, $hk$waaḥid$hk$, $hk$Number$hk$, $hk$Feminine واحدة for ة-words: بنت واحدة. Comes after the noun, not before: شاهي واحد 'one tea'. Also 'someone': واحد من صنعاء 'a guy from Sanaa'.$hk$, $hk$One single tea glass on a plain tray, large numeral 1 beside it.$hk$, $hk$شاهي واحد لو سمحت$hk$, $hk$shaahi waaḥid law samaḥt$hk$, $hk$One tea, please$hk$, 1),
  ($hk$ثنين$hk$, $hk$two$hk$, $hk$thnayn$hk$, $hk$Number$hk$, $hk$Sanaa keeps the th: thnayn, not the Aden or Egyptian itneen. Feminine ثنتين. Yemeni also has a 'two' ending on the noun itself — ريالين 'two riyals', شاهيين — which you will hear before you need to say it.$hk$, $hk$Two tea glasses side by side on a tray, numeral 2 beside them.$hk$, $hk$ثنين شاهي$hk$, $hk$thnayn shaahi$hk$, $hk$Two teas$hk$, 2),
  ($hk$ثلاثة$hk$, $hk$three$hk$, $hk$thalaatha$hk$, $hk$Number$hk$, $hk$Two th sounds in one word — the clearest place to hear that Sanaa keeps them (Aden says talaata). From three to ten the number comes before the thing: ثلاثة جهّال 'three children'.$hk$, $hk$Three flatbreads stacked on a straw mat, numeral 3 beside them.$hk$, $hk$عندي ثلاثة جهّال$hk$, $hk$ʿindi thalaatha jahhaal$hk$, $hk$I have three children$hk$, 3),
  ($hk$أربعة$hk$, $hk$four$hk$, $hk$arbaʿa$hk$, $hk$Number$hk$, $hk$The ع in the middle is a squeeze in the throat between two a's — ar-ba-ʿa. Four is also the number of cups in a standard pot of qishr.$hk$, $hk$Four small coffee cups arranged in a square on a brass tray, numeral 4.$hk$, $hk$أربعة كتب على الكرسي$hk$, $hk$arbaʿa kutub ʿala l-kursi$hk$, $hk$Four books on the chair$hk$, 4),
  ($hk$خمسة$hk$, $hk$five$hk$, $hk$khamsa$hk$, $hk$Number$hk$, $hk$Starts with خ. The open hand is five, and خمسة is also said to ward off the evil eye — a hand-shaped charm hangs in many shops.$hk$, $hk$An open right hand, palm forward, fingers spread, numeral 5 beside it.$hk$, $hk$الخبز بخمسة ريال$hk$, $hk$il-khubz bi-khamsa riyaal$hk$, $hk$The bread is five riyals$hk$, 5),
  ($hk$ستة$hk$, $hk$six$hk$, $hk$sitta$hk$, $hk$Number$hk$, $hk$Doubled t — hold it. Same word across the Arab world; nothing to unlearn.$hk$, $hk$Six eggs in a cardboard carton, numeral 6 beside it.$hk$, $hk$ستة بيض لو سمحت$hk$, $hk$sitta bayḍ law samaḥt$hk$, $hk$Six eggs, please$hk$, 6),
  ($hk$سبعة$hk$, $hk$seven$hk$, $hk$sabʿa$hk$, $hk$Number$hk$, $hk$The ع is right after the b, so the word is sab-ʿa with the throat closing between the halves. Yemen's phone numbers start with 7, so this digit is heard constantly.$hk$, $hk$Seven qat leaves fanned out on a cloth, numeral 7 beside them.$hk$, $hk$رقمي سبعة سبعة ثلاثة$hk$, $hk$ragmi sabʿa sabʿa thalaatha…$hk$, $hk$My number is seven seven three…$hk$, 7),
  ($hk$ثمانية$hk$, $hk$eight$hk$, $hk$thamaaniya$hk$, $hk$Number$hk$, $hk$Four syllables and a th at the start: tha-maa-ni-ya. Often clipped to ثمان before a noun and when telling the time: الساعة ثمان 'eight o'clock'.$hk$, $hk$Eight dates on a small plate, numeral 8 beside it.$hk$, $hk$ثمانية ريال$hk$, $hk$thamaaniya riyaal$hk$, $hk$Eight riyals$hk$, 8),
  ($hk$تسعة$hk$, $hk$nine$hk$, $hk$tisʿa$hk$, $hk$Number$hk$, $hk$tis-ʿa, the ع again before the final a. Yemeni's short i in the first syllable (not tas-) is the giveaway of a native speaker.$hk$, $hk$Nine small keys hung on a wooden board, numeral 9 beside it.$hk$, $hk$تسعة كراسي$hk$, $hk$tisʿa karaasi$hk$, $hk$Nine chairs$hk$, 9),
  ($hk$عشرة$hk$, $hk$ten$hk$, $hk$ʿashara$hk$, $hk$Number$hk$, $hk$Starts with ع. Clipped to عشر before a noun and in times: الساعة عشر. Ten riyals is the smallest note you will handle.$hk$, $hk$Both hands open, palms forward, all ten fingers spread, numeral 10 beside them.$hk$, $hk$عشرة ريال$hk$, $hk$ʿashara riyaal$hk$, $hk$Ten riyals$hk$, 10),
  ($hk$بكم$hk$, $hk$how much (price)$hk$, $hk$bikam$hk$, $hk$Question$hk$, $hk$'For how much' — the price question, with the بـ built in. Plain كم is 'how many' for counting. Point and say بكم ذا؟ and every vendor in Yemen understands you.$hk$, $hk$A customer pointing at a pile of tomatoes with a questioning look at the vendor.$hk$, $hk$بكم الشاهي؟$hk$, $hk$bikam ish-shaahi?$hk$, $hk$How much is the tea?$hk$, 11),
  ($hk$زلط$hk$, $hk$money$hk$, $hk$zalaṭ$hk$, $hk$Noun$hk$, $hk$The Sanaa word for money — the one that marks you as having learned Yemeni rather than textbook Arabic. فلوس is understood everywhere and is what the south says. Both appear in captions.$hk$, $hk$A fan of Yemeni riyal banknotes held in a hand.$hk$, $hk$معي زلط$hk$, $hk$maʿi zalaṭ$hk$, $hk$I have money on me$hk$, 12),
  ($hk$ريال$hk$, $hk$riyal (Yemeni currency)$hk$, $hk$riyaal$hk$, $hk$Noun$hk$, $hk$The unit of every price. Stays singular after a number (خمسة ريال) and takes the two-ending for two: ريالين. Also the name of the Saudi currency, which circulates in parts of Yemen — context says which.$hk$, $hk$A single Yemeni banknote lying flat, the numeral large and clear.$hk$, $hk$الكتاب بعشرة ريال$hk$, $hk$il-kitaab bi-ʿashara riyaal$hk$, $hk$The book is ten riyals$hk$, 13)
) AS v(word_arabic, word_english, transliteration, category, teaching_note, image_scene_description, example_arabic, example_transliteration, example_english, display_order)
CROSS JOIN public.lessons l
WHERE l.source_key = $hk$yemeni/s1/l06$hk$
  AND NOT EXISTS (SELECT 1 FROM public.vocabulary_words w WHERE w.lesson_id = l.id AND w.word_arabic = v.word_arabic);
UPDATE public.vocabulary_words w
SET word_english = v.word_english, transliteration = v.transliteration, category = v.category, teaching_note = v.teaching_note, image_scene_description = v.image_scene_description, example_arabic = v.example_arabic, example_transliteration = v.example_transliteration, example_english = v.example_english, display_order = v.display_order
FROM (VALUES
  ($hk$واحد$hk$, $hk$one$hk$, $hk$waaḥid$hk$, $hk$Number$hk$, $hk$Feminine واحدة for ة-words: بنت واحدة. Comes after the noun, not before: شاهي واحد 'one tea'. Also 'someone': واحد من صنعاء 'a guy from Sanaa'.$hk$, $hk$One single tea glass on a plain tray, large numeral 1 beside it.$hk$, $hk$شاهي واحد لو سمحت$hk$, $hk$shaahi waaḥid law samaḥt$hk$, $hk$One tea, please$hk$, 1),
  ($hk$ثنين$hk$, $hk$two$hk$, $hk$thnayn$hk$, $hk$Number$hk$, $hk$Sanaa keeps the th: thnayn, not the Aden or Egyptian itneen. Feminine ثنتين. Yemeni also has a 'two' ending on the noun itself — ريالين 'two riyals', شاهيين — which you will hear before you need to say it.$hk$, $hk$Two tea glasses side by side on a tray, numeral 2 beside them.$hk$, $hk$ثنين شاهي$hk$, $hk$thnayn shaahi$hk$, $hk$Two teas$hk$, 2),
  ($hk$ثلاثة$hk$, $hk$three$hk$, $hk$thalaatha$hk$, $hk$Number$hk$, $hk$Two th sounds in one word — the clearest place to hear that Sanaa keeps them (Aden says talaata). From three to ten the number comes before the thing: ثلاثة جهّال 'three children'.$hk$, $hk$Three flatbreads stacked on a straw mat, numeral 3 beside them.$hk$, $hk$عندي ثلاثة جهّال$hk$, $hk$ʿindi thalaatha jahhaal$hk$, $hk$I have three children$hk$, 3),
