SELECT 'grammar', $hk$verb-conjugation$hk$, $hk$Yemeni$hk$, $hk$Verb conjugation$hk$, $hk$A1$hk$, s.id, 'curriculum-tracks', '{}'::jsonb
FROM public.curriculum_stages s WHERE s.stage_number = 1
