SELECT c.id, $hk$Yemeni$hk$, $hk$لحم$hk$, ARRAY[$hk$اللحم$hk$, $hk$لحمة$hk$, $hk$لحمه$hk$, $hk$لحم غنم$hk$]::text[], $hk$laḥm$hk$, 'draft', 'curriculum-tracks'
