INSERT INTO public.vocabulary_words (lesson_id, dialect_module, word_arabic, word_english, transliteration, category, teaching_note, image_scene_description, example_arabic, example_transliteration, example_english, display_order)
SELECT l.id, $hk$Yemeni$hk$, v.word_arabic, v.word_english, v.transliteration, v.category, v.teaching_note, v.image_scene_description, v.example_arabic, v.example_transliteration, v.example_english, v.display_order
FROM (VALUES
  ($hk$أظن$hk$, $hk$I think$hk$, $hk$aẓunn$hk$, $hk$Verb$hk$, $hk$The safest opinion verb. ظ is the heavy dh: aẓunn. Followed by إن. You will also hear أحسب (very Sanaa) and أعتقد.$hk$, $hk$A man with a finger on his temple and a thought bubble with a question mark.$hk$, $hk$أظن إنه بيجي بكرة$hk$, $hk$aẓunn innuh bi-yiji bukra$hk$, $hk$I think he's coming tomorrow$hk$, 1),
  ($hk$في رأيي$hk$, $hk$in my opinion$hk$, $hk$fi raʾyi$hk$, $hk$Expression$hk$, $hk$Fronts an opinion and makes it personal, which is polite. برأيي is the same. Ask back with ايش رأيك؟$hk$, $hk$A woman with one hand on her chest and the other open, speaking calmly.$hk$, $hk$في رأيي، الشاهي العدني أحلى$hk$, $hk$fi raʾyi, ish-shaahi l-ʿadani aḥla$hk$, $hk$In my opinion, Adeni tea is nicer$hk$, 2),
  ($hk$موافق$hk$, $hk$agree / I agree$hk$, $hk$muwaafig$hk$, $hk$Adjective$hk$, $hk$A participle: أنا موافق 'I agree', موافقة for a woman, موافقين for us. ق is g. The one-word yes to a proposal.$hk$, $hk$Two men shaking hands with nods, a thumbs-up from a third.$hk$, $hk$أنا موافق معك مية بالمية$hk$, $hk$ana muwaafig maʿak miyya bil-miyya$hk$, $hk$I agree with you a hundred percent$hk$, 3),
  ($hk$مش موافق$hk$, $hk$disagree / I don't agree$hk$, $hk$mish muwaafig$hk$, $hk$Expression$hk$, $hk$The plain disagreement: مش before the participle. Soften it with معليش بس or عندك حق بس. مش موافقة for a woman.$hk$, $hk$A man shaking his head with a raised palm, calm face.$hk$, $hk$معليش، بس أنا مش موافق على هذا$hk$, $hk$maʿleesh, bass ana mish muwaafig ʿala haadha$hk$, $hk$Sorry, but I don't agree with this$hk$, 4),
  ($hk$مبسوط$hk$, $hk$happy / pleased$hk$, $hk$mabsuuṭ$hk$, $hk$Adjective$hk$, $hk$The everyday 'happy': مبسوط من الشغل 'happy with work'. فرحان is the bigger joy. Feminine مبسوطة.$hk$, $hk$A young man grinning widely, arms wide, on a sunny rooftop.$hk$, $hk$أنا مبسوط إنك جيت$hk$, $hk$ana mabsuuṭ innak jiit$hk$, $hk$I'm happy that you came$hk$, 5),
  ($hk$حانق$hk$, $hk$angry$hk$, $hk$ḥaanig$hk$, $hk$Adjective$hk$, $hk$The Yemeni 'angry' — from حنق. حانق منك 'angry at you', حنقت 'I got angry', لا تحنق 'don't be angry'. زعلان is milder, more 'upset'.$hk$, $hk$A man with furrowed brows and clenched fist, steam-style lines around his head.$hk$, $hk$ليش أنت حانق اليوم؟$hk$, $hk$leesh ant ḥaanig il-yawm?$hk$, $hk$Why are you angry today?$hk$, 6),
  ($hk$زهقان$hk$, $hk$bored / fed up$hk$, $hk$zahgaan$hk$, $hk$Adjective$hk$, $hk$ق is g: zahgaan. زهقت 'I'm bored / fed up', ملّيت is the older Sanaa word. Feminine زهقانة.$hk$, $hk$A teenager slumped on a cushion staring at a blank wall, phone dead.$hk$, $hk$زهقان من البيت، نطلع نتمشى؟$hk$, $hk$zahgaan min il-bayt, niṭlaʿ nitmashsha?$hk$, $hk$I'm bored of the house, shall we go for a walk?$hk$, 7),
  ($hk$مهموم$hk$, $hk$worried$hk$, $hk$mahmuum$hk$, $hk$Adjective$hk$, $hk$From هم 'worry' — the Yemeni series همي همك means 'my worry is your worry'. مهموم على 'worried about'. Also قلقان and خايف على.$hk$, $hk$A woman looking at her phone with a hand on her cheek, night outside.$hk$, $hk$أنا مهموم على أخوي في الغربة$hk$, $hk$ana mahmuum ʿala akhuuy fil-ghurba$hk$, $hk$I'm worried about my brother abroad$hk$, 8),
  ($hk$يعجبني$hk$, $hk$I like (it pleases me)$hk$, $hk$yiʿjibni$hk$, $hk$Verb$hk$, $hk$Literally 'it pleases me', so the thing is the subject: يعجبني القات 'I like qat', تعجبني صنعاء 'I like Sanaa' (feminine). أحب is 'I love / I like' too.$hk$, $hk$A man giving a delighted thumbs-up at a plate of saltah.$hk$, $hk$يعجبني البرد في صنعاء$hk$, $hk$yiʿjibni l-bard fi ṣanʿaa$hk$, $hk$I like the cold in Sanaa$hk$, 9),
  ($hk$أكره$hk$, $hk$I hate$hk$, $hk$akrah$hk$, $hk$Verb$hk$, $hk$Strong but common: أكره الزحمة 'I hate traffic'. ما أحبش is the gentler 'I don't like'.$hk$, $hk$A woman wrinkling her nose at a plate of something, pushing it away.$hk$, $hk$أكره الحر في الحديدة$hk$, $hk$akrah il-ḥarr fil-ḥudayda$hk$, $hk$I hate the heat in Hodeidah$hk$, 10),
  ($hk$أحس$hk$, $hk$I feel$hk$, $hk$aḥiss$hk$, $hk$Verb$hk$, $hk$Both body and opinion: أحس بتعب 'I feel tired', أحس إنه غلط 'I feel it's wrong'. Doubled s at the end.$hk$, $hk$A woman with a hand on her forehead and a thought bubble with a thermometer.$hk$, $hk$أحس إن الغدا كان كثير$hk$, $hk$aḥiss inn il-ghada kaan kathiir$hk$, $hk$I feel lunch was too much$hk$, 11),
  ($hk$رأي$hk$, $hk$opinion$hk$, $hk$raʾy$hk$, $hk$Noun$hk$, $hk$ايش رأيك؟ 'what do you think?' is the invitation to every debate. رأيي 'my opinion', آراء 'opinions'.$hk$, $hk$A speech bubble with a lightbulb inside, held up like a sign.$hk$, $hk$ايش رأيك في المطعم الجديد؟$hk$, $hk$aysh raʾyak fil-maṭʿam ij-jadiid?$hk$, $hk$What's your opinion of the new restaurant?$hk$, 12),
  ($hk$بصراحة$hk$, $hk$frankly / honestly$hk$, $hk$bi-ṣaraaḥa$hk$, $hk$Adverb$hk$, $hk$Signals a blunt opinion is coming — and softens it at the same time. بصراحة، ما عجبنيش 'frankly, I didn't like it'.$hk$, $hk$A man leaning in with an open hand, eyebrows up, about to speak plainly.$hk$, $hk$بصراحة، الفيلم ما عجبنيش$hk$, $hk$bi-ṣaraaḥa, il-film maa ʿajabniish$hk$, $hk$Frankly, I didn't like the film$hk$, 13),
  ($hk$غلط$hk$, $hk$wrong$hk$, $hk$ghalaṭ$hk$, $hk$Adjective$hk$, $hk$هذا غلط 'this is wrong', أنت غلطان 'you're mistaken'. Used for facts and behaviour alike; the noun 'a mistake' is غلطة.$hk$, $hk$A large red cross over a maths sum on a blackboard.$hk$, $hk$الجواب غلط، جرّب مرة ثانية$hk$, $hk$ij-jawaab ghalaṭ, jarrib marra thaanya$hk$, $hk$The answer is wrong, try again$hk$, 14),
  ($hk$صح$hk$, $hk$right / correct$hk$, $hk$ṣaḥḥ$hk$, $hk$Adjective$hk$, $hk$The opposite of غلط and also the tag 'right?': غالي، صح؟ Double the ḥ. صحيح is the longer form.$hk$, $hk$A big green tick on a whiteboard, a teacher nodding.$hk$, $hk$أنت من تعز، صح؟$hk$, $hk$ant min taʿizz, ṣaḥḥ?$hk$, $hk$You're from Taiz, right?$hk$, 15),
  ($hk$عندك حق$hk$, $hk$you're right$hk$, $hk$ʿindak ḥagg$hk$, $hk$Expression$hk$, $hk$The softener before every disagreement: عندك حق، بس… To a woman عندش حق (Sanaa -ish). ق is g: ḥagg.$hk$, $hk$A man nodding with a hand raised in concession to a friend.$hk$, $hk$عندك حق، بس القات غالي قوي$hk$, $hk$ʿindak ḥagg, bass il-gaat ghaali gawi$hk$, $hk$You're right, but qat is really expensive$hk$, 16),
  ($hk$بالعكس$hk$, $hk$on the contrary$hk$, $hk$bil-ʿaks$hk$, $hk$Expression$hk$, $hk$Flips a claim: مش غالي، بالعكس، رخيص 'not expensive — the opposite, cheap'. Very common in friendly argument.$hk$, $hk$Two arrows pointing opposite ways, a woman pointing the other way.$hk$, $hk$ما زهقتش، بالعكس، انبسطت$hk$, $hk$maa zahigtsh, bil-ʿaks, inbasaṭt$hk$, $hk$I wasn't bored, on the contrary, I enjoyed myself$hk$, 17),
  ($hk$معقول$hk$, $hk$reasonable / plausible$hk$, $hk$maʿguul$hk$, $hk$Adjective$hk$, $hk$ق is g: maʿguul. سعر معقول 'a reasonable price'; as a question معقول؟ means 'is that even possible?'. مش معقول 'unbelievable'.$hk$, $hk$A shopkeeper and customer nodding over a price tag.$hk$, $hk$السعر معقول، في رأيي$hk$, $hk$is-siʿr maʿguul, fi raʾyi$hk$, $hk$The price is reasonable, in my opinion$hk$, 18)
) AS v(word_arabic, word_english, transliteration, category, teaching_note, image_scene_description, example_arabic, example_transliteration, example_english, display_order)
CROSS JOIN public.lessons l
WHERE l.source_key = $hk$yemeni/s3/l04$hk$
  AND NOT EXISTS (SELECT 1 FROM public.vocabulary_words w WHERE w.lesson_id = l.id AND w.word_arabic = v.word_arabic);
UPDATE public.vocabulary_words w
