INSERT INTO public.curriculum_concepts (kind, key, dialect, display_english, cefr_level, stage_id, source_type, metadata)
SELECT 'grammar', $hk$sentence-structure$hk$, $hk$Yemeni$hk$, $hk$Sentence structure$hk$, $hk$B1$hk$, s.id, 'curriculum-tracks', '{}'::jsonb
FROM public.curriculum_stages s WHERE s.stage_number = 3
ON CONFLICT (kind, key, dialect) DO NOTHING;
