FROM public.curriculum_concepts c, public.lessons l
WHERE c.kind = 'grammar' AND c.key = $hk$sentence-structure$hk$ AND c.dialect = $hk$Yemeni$hk$ AND l.source_key = $hk$yemeni/s3/l05$hk$
ON CONFLICT (concept_id, content_type, content_id, role) DO NOTHING;
